INSERT INTO extras (id, title, content, type, rules_type, season, tags, ssk_name, created_at) VALUES ('5f98a20c-1dd2-4826-ae4b-f88705311812', 'Current status of the FIVB rule tests', '<p class="ql-align-justify">At the central course in Magglingen we informed you which rules of the FIVB rule test 2026 would be adopted for the coming season, following a decision of the Swiss Volley Central Board. In taking that decision, the Central Board relied on the information available from the CEV at the time.</p><p class="ql-align-justify">In the meantime, the CEV has changed its mind and adopted all FIVB rule tests 2026 with immediate effect for all official CEV matches.</p><p class="ql-align-justify">In its original decision, the Central Board had already decided that, should the rule tests nevertheless be introduced at short notice before the start of the championship, they would not be adopted in full. Only the changes concerning the &quot;first movement at the service&quot; and the new application of Rule 9.2.2 &quot;held and thrown attack balls&quot; are adopted. For the national championship, the rule changes and adjustments therefore remain those we explained and practised at the central course.</p><p class="ql-align-justify">For matches of Swiss teams in the European Cups, however, the new rule changes of the FIVB rule tests 2026 apply. This is particularly important for the line judges of the top group. The explanations can be found in title 6 of the SSK document &quot;Rule changes – explanations for referees&quot;.</p>', 'post', 'ssk', '2026/2027', '["Rules"]', '26 - 4', '2026-10-09 08:00:00');
INSERT INTO extras (id, title, content, type, rules_type, season, tags, ssk_name, created_at) VALUES ('b18eb897-ee7a-49ab-8084-a07274406f00', 'Information from the RD seminar', '<p class="ql-align-justify">The annual SSK RD seminar took place on 13 September 2026. The focus was on implementing the season objectives and on further aligning the evaluation and assessment criteria.</p><p class="ql-align-justify">A central concern of the SSK is to make the evaluations as objective as possible. At the same time, we are aware that a completely objective evaluation will never be possible. Different match conditions, the composition of the refereeing team and the experience and competence of each RD always have a noticeable influence on the assessment.</p><p class="ql-align-justify"><strong>Evaluation tools developed further</strong></p><p class="ql-align-justify">At the seminar, the observation form was adapted to the current season objectives. The evaluation guidelines, in particular the meaning of &quot;GOOD&quot;, &quot;VERY GOOD&quot; and so on, were also discussed together (see also the central course presentation).</p><p class="ql-align-justify">The meaning of the arrows in the observation form was also clarified:</p><ul><li>✓ masters the requirements of this match;</li><li>↑ potential for more demanding matches;</li><li>↓ seems to be overstretched by this match.</li></ul><p class="ql-align-justify">This is to ensure that the evaluations are understood and applied as uniformly as possible.</p><p class="ql-align-justify"><strong>Self-reflection: critical and accurate</strong></p><p class="ql-align-justify">For the evaluation of the self-reflection we concentrate on points b, d and e. What matters is that a critical and concrete examination of your own performance is recognisable.</p><p class="ql-align-justify">A statement such as &quot;The cooperation was good&quot; is therefore of little help. More meaningful is, for example, &quot;Because you regularly signalled to me in close situations, I was able to decide with confidence&quot;.</p><p class="ql-align-justify">The self-reflection should therefore not only give a general assessment but show concrete insights from the match. The RDs are aware that your feedback must not have any negative influence on their neutral observation.</p><p class="ql-align-justify"><strong>Cooperation in the refereeing team</strong></p><p class="ql-align-justify">The cooperation between the 1st and 2nd referee will continue to be observed closely. Checks should visibly be carried out together, the preparation should be done as a team, and the checks at the start of a set should also be synchronised.</p><p class="ql-align-justify">If these joint procedures are not followed and errors result from this, the evaluation applies to both referees. Since the evaluation is meant to correct a corresponding pattern of behaviour, this can lead to a mark of &quot;e&quot; or &quot;f&quot;.</p><p class="ql-align-justify"><strong>Team discipline</strong></p><p class="ql-align-justify">Another focus of the season is team discipline. Referees should apply their knowledge of the rules with confidence and consistently follow the intended processes. This includes in particular:</p><ul><li>the game captain is known at all times;</li><li>the sanctioning scale is applied correctly;</li><li>the intended procedures are carried out completely and in sequence;</li><li>sanctions can be correctly justified to the teams;</li><li>lack of discipline is recognised and sanctioned appropriately to the situation;</li><li>the 1st and 2nd referee support each other and exchange relevant information.</li></ul><p class="ql-align-justify">If the intended sanctioning processes are not carried out correctly, this is in principle marked with an &quot;e&quot;. If a single process step is omitted, a &quot;d&quot; may be given where appropriate.</p><p class="ql-align-justify">For carrying out sanctions, the SSK expects a clear and calm approach.</p><p class="ql-align-justify"><strong>Sanctioning processes: consistent and sequential</strong></p><p class="ql-align-justify">Player on court – Guidelines (20/21, 3.1):</p><ol><li>whistle;</li><li>player to the referee;</li><li>justification of the sanction;</li><li>take out and show the card only after the justification;</li><li>no further discussion; ask to resume play;</li><li>the 2nd referee observes the whole procedure and the teams, then checks that the scorer has recorded the sanction.</li></ol><p class="ql-align-justify">Team member not on court – Guidelines (20/21, 3.1):</p><ol><li>whistle;</li><li>game captain to the referee;</li><li>name the offending team member and justify the sanction;</li><li>the game captain informs the team member concerned;</li><li>take out and show the card;</li><li>the team member acknowledges;</li><li>if it is not clear to the 2nd referee whom the sanction concerns, he/she finds out;</li><li>the 2nd referee informs the scorer and checks that the sanction has been recorded.</li></ol><p class="ql-align-justify"><strong>Our common goal</strong></p><p class="ql-align-justify">Uniform procedures, comprehensible evaluations and a consistent implementation of the season objectives should help to further improve the quality and comparability of refereeing performances.</p>', 'post', 'ssk', '2026/2027', '["Referees"]', '26 - 4', '2026-10-09 08:07:00');
INSERT INTO extras (id, title, content, type, rules_type, season, tags, ssk_name, created_at) VALUES ('32bd0a22-f36b-4ef4-b45f-cdb96f0c463b', 'E-scoresheet: reporting poor performance by e-scorers', '<p class="ql-align-justify">Until now, NLA teams had to register at least two, but no more than four, e-scorers in the official scorer list. At the last Swiss Volley League Conference (SVLK), the NLA teams decided to raise the maximum number of e-scorers that can be registered to six.</p><p class="ql-align-justify">The SSK and the MKI did not support this proposal, as we are convinced that the quality of the e-scorers will suffer even more as a result, which in turn will lead to more problems and interruptions during matches.</p><p class="ql-align-justify">The SSK has informed the Swiss Volley office that we will report future problems with e-scorers to the office. In such cases the SSK also expects the office to take the matter up with the club concerned and initiate the necessary measures.</p><p class="ql-align-justify">So that such feedback can be given, please report incidents with e-scorers from now on to Praesident.SSK@volleyball.ch.</p>', 'post', 'ssk', '2026/2027', '["Guidelines"]', '26 - 4', '2026-10-09 08:42:00');
INSERT INTO extras (id, title, content, type, rules_type, season, tags, ssk_name, created_at) VALUES ('1290f668-82f1-4635-959e-d94b050a6466', 'Game management: keeping the whole match in view', '<p class="ql-align-justify">In an NLB women&#x27;s match, the first referee made the correct decision, but the scorer credited the point to the wrong team. This was not noticed by either referee, nor was it noticed afterwards that, as a result, the wrong player according to the e-scoresheet went to serve.</p><p class="ql-align-justify">The work of referees is not limited to recognising and penalising faults. We have to keep the entire environment of the match under control. That, among other things, is what we mean by game management.</p><p class="ql-align-justify">This also includes checking whether the points are recorded correctly, whether the right player goes to serve and whether the starting line-up is correct. With the tablet we have a control tool that makes this task considerably easier.</p><p class="ql-align-justify">Such errors should really not happen to us. The SSK therefore asks you to always be aware of your many control tasks and to carry them out consistently.</p><p class="ql-align-justify">The protest lodged by the visiting team was subsequently not upheld.</p>', 'post', 'ssk', '2026/2027', '["Guidelines"]', '26 - 4', '2026-10-09 08:49:00');
